const components:Record<CategoryIconId,Component>={food:Utensils,breakfast:Sunrise,night:Moon,coffee:Coffee,takeout:Soup,dessert:CakeSlice,vegetables:Carrot,basket:ShoppingBasket,fruit:Apple,car:Car,bus:Bus,bike:Bike,fuel:Fuel,parking:SquareParking,drive:CircleGauge,train:TrainFront,subway:TramFront,travel:Plane,departure:PlaneTakeoff,walk:Footprints,house:House,building:Building2,water:Droplet,electricity:Zap,wifi:Wifi,renovation:Hammer,repair:Wrench,bed:BedDouble,furniture:Sofa,bag:ShoppingBag,cart:ShoppingCart,clothes:Shirt,phone:Smartphone,beauty:Smile,pet:PawPrint,package:Package,game:Gamepad2,movie:Popcorn,music:MicVocal,ticket:Ticket,party:PartyPopper,fitness:Dumbbell,health:BriefcaseMedical,medicine:Pill,heart:HeartPulse,study:GraduationCap,book:BookOpen,course:NotebookPen,gift:Gift,envelope:MailOpen,people:Users,card:CreditCard,money:Banknote,wallet:Wallet,store:Store,chart:ChartNoAxesCombined,refund:Undo2,income:ArrowDownLeft,receipt:ReceiptText,star:Star,plus:Plus,tag:Tag,grid:Grid2X2}
