</script>
<template><component v-if="resolved.kind==='svg'" :is="components[resolved.key]" class="category-icon-svg" :data-category-icon="resolved.key" :width="size" :height="size" :stroke-width="1.9" :style="{color}" aria-hidden="true" focusable="false"/><span v-else class="category-icon-emoji" data-category-icon="custom-emoji" :style="{color,fontSize:`${size}px`,width:`${size}px`,height:`${size}px`}" aria-hidden="true">{{ resolved.value }}</span></template>
<style scoped>.category-icon-svg{display:block;flex:none;overflow:visible;stroke-linecap:round;stroke-linejoin:round}.category-icon-emoji{display:inline-grid;place-items:center;flex:none;line-height:1;font-family:"Apple Color Emoji","Segoe UI Emoji","Noto Color Emoji",sans-serif}</style>
